window.NOTES={"version":47,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":25,"chapter":10,"section":"10.1","type":"多选","topic":"关系运算","title":"选择、投影、连接与集合运算","trigger":"真题从WHERE对应、单表取行列、多表组合和“只属于一个集合”考查关系代数。","conclusion":"选择筛选行，投影取得列并按关系代数的集合语义去重，连接按匹配条件组合元组；并、交、差还要检查两侧关系是否相容。","points":["从人员表筛出男性使用选择，再只保留编号、姓名、性别使用投影；若需要全部人员的指定字段，不必额外增加行条件。","关系代数的结果仍是集合，所以投影会消除重复元组。例如班级列为A、B、A，投影班级只得到A、B；普通SQL SELECT默认可保留重复行，SELECT DISTINCT才去重。","自然连接按全部同名属性相等匹配，公共属性在输出中只保留一列；自然内连接不保留未匹配行。若两表同名列有“学号、班级”，(01,A)不能匹配(01,B)，只让学号相等还不够。","连接不是按两表的显示行号一一拼接；同一个连接值若匹配多行，应产生所有匹配组合。要按指定字段连接时，应明确连接条件。","并、交、差要求两侧列数相同且对应列的域或数据类型相容；字段名或顺序不一致时要先明确对应关系，不能把任意两张表直接做集合运算。","S−T只保留属于S而不属于T的元组，方向不能颠倒；“仅属于两集合之一”是(S−T)∪(T−S)，不是单独的S−T。","跨表获取相关信息通常可理解为先连接，再按目标选择行、投影列；这是语义分析方式，不是强制数据库按同一物理顺序执行。","笛卡儿积（也称笛卡尔积）把两关系的每个元组两两组合；两侧分别有m、n行时得到m×n种组合。2020年第25题只需在同一学生表选择女同学的行，再投影姓名列，无需连接或笛卡儿积。"],"boundary":"关系代数的“选择”对应筛行，不等于SQL命令名SELECT的全部作用；投影去重、集合相容性和连接匹配条件都不能省略。","id":"merged-20","sources":[{"year":2020,"q":25,"type":"多选"},{"year":2023,"q":46,"type":"填空"},{"year":2024,"q":14,"type":"单选"},{"year":2026,"q":11,"type":"单选"},{"year":2022,"q":27,"type":"多选"},{"year":2021,"q":13,"type":"单选","page":3}],"keys":["2020-25","2023-46","2024-14","2026-11","2022-27","2021-13"],"comparison":{"headers":["运算","主要改变","易错边界"],"rows":[["选择σ","保留满足条件的行","列结构不因此减少"],["投影π","保留指定列","关系代数结果去重"],["自然连接⋈","组合所有同名属性相等的元组","不是按显示行号拼接"],["差S−T","保留S有而T没有的元组","有方向且要求关系相容"],["笛卡儿积×","两侧元组的全部组合","m行与n行得到m×n行，不附加匹配条件"]]},"pointGroups":[{"title":"行、列与跨表匹配","indices":[0,1,2,3]},{"title":"集合运算与组合使用","indices":[4,5,6,7]}],"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"把筛行、取列映射到WHERE和SELECT，同时注意关系代数投影去重与SQL默认保留重复的差别。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"理解连接匹配和结果重复前，先分清属性、主键、外键及某列是否由业务规则保证唯一。"},{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多、多对多联系决定跨表匹配的可能数量，连接不能按屏幕行号机械拼接。"}],"workedExamples":[{"year":2024,"q":14,"questionSummary":"从两个报名集合中找只参加第一项的学生。","reasoning":["S代表第一项报名，T代表第二项报名；目标要求同时满足属于S与不属于T。","因此用差集S−T；两关系属性相同，满足本题集合运算的相容前提。","交集是两项都参加，并集是至少一项参加，T−S会把方向倒过来。"],"pitfall":"把“只参加100米”看成两项都参加，或把差集方向颠倒。","transfer":"如果改问只参加其中一项，应取(S−T)∪(T−S)，不是单独一个差集。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"公开转录题面已读，原卷扫描待核","historicalVersionNote":""},{"year":2020,"q":25,"questionSummary":"从学生表中取得女同学姓名，判断需要的关系运算。","reasoning":["先按性别条件取符合的行，这是选择。","再只保留姓名这一属性，这是投影。","所需字段都在同一关系中，无需额外连接或做笛卡儿积。"],"pitfall":"把SQL关键词SELECT直译成关系代数中的单一“选择”，忽略取列还涉及投影。","transfer":"改成查询全部学生姓名时只需投影；改成跨两表取得课程成绩时再考虑连接。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"公开转录题面已读，原卷扫描待核","historicalVersionNote":""}]},{"q":35,"chapter":10,"section":"10.1","type":"填空","topic":"SQL查询","title":"SELECT查询与字段选择","trigger":"两道题分别考查SQL查询命令和星号的含义。","conclusion":"SELECT指定结果列，FROM指定数据来源，WHERE筛选行，ORDER BY规定输出顺序；星号只代表来源中的全部列，不能据此断定全部行都会返回。","points":["基本结构可写为SELECT 字段 FROM 表 WHERE 条件 ORDER BY 字段；是否返回某行还取决于WHERE、连接及其他查询条件。","SELECT默认可能保留重复结果；需要去重时使用DISTINCT。GROUP BY用于分组，不应拿它代替单纯的去重或排序说明。","没有ORDER BY时，不保证按插入顺序、主键顺序或屏幕上原来的顺序返回。排序值相同且需要固定次序时，可追加学号等排序键。","WHERE只保留条件为真的行；NULL表示未知或缺失，判断它应写IS NULL或IS NOT NULL，不能写“= NULL”。","例如SELECT 姓名 FROM 学生 WHERE 成绩 &gt;= 60只返回达标学生姓名；成绩为NULL不自动等于0，也不会使该比较条件成立。","实际应用宜明确列出所需字段，减少无用传输并稳定结果结构；ORDER BY排列查询结果，不修改源表数据。"],"boundary":"SELECT *的星号表示所有列，不是所有行；NULL不是0或空字符串，结果排序也不等于更新源数据。","id":"merged-21","sources":[{"year":2020,"q":35,"type":"填空"},{"year":2026,"q":43,"type":"填空"}],"keys":["2020-35","2026-43"],"comparison":{"headers":["语句部分","作用"],"rows":[["SELECT 姓名,成绩","决定返回哪些列"],["WHERE 成绩 >= 60","决定保留哪些行"],["SELECT DISTINCT 性别","去除结果中的重复行"],["ORDER BY 成绩 DESC,学号 ASC","决定结果次序及同分时的次序"],["成绩 IS NULL","查找缺失成绩"]]},"related":[{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"用关系代数区分选择行、投影列和连接来源，解释SELECT命令并不只对应其中的选择运算。"},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"UPDATE前可用相同WHERE查询核对目标行，查询条件的理解直接决定修改范围。"},{"id":"y2020q9","label":"高级筛选同一行是AND，不同行是OR","reason":"SQL筛行和Excel高级筛选都要求正确组合条件，同行AND、异行OR可帮助练习条件分组。"}],"pointGroups":[{"title":"确定来源、筛选行并处理NULL","indices":[0,3,4]},{"title":"组织结果列、去重与排序","indices":[1,2,5]}]},{"q":14,"chapter":10,"section":"10.1","type":"单选","topic":"关系模型","title":"属性、域、候选码、主键与外键要分层判断","trigger":"题目要求辨认关系模型中属性取值范围、行和列的术语。","conclusion":"关系的一行称元组，一列对应属性，属性允许取值的集合称域；候选码还必须是能够唯一标识元组且不含多余属性的最小属性集合。","points":["先把学生关系看成有明确列含义的二维表：“01、王宁、女”整行是一个元组，“姓名”这一列是属性。若本例规定性别域为{男、女、未说明}，域就包含尚未在当前表中出现的“未说明”。关系模式描述名称、属性和约束，当前记录是关系实例。","超码能唯一标识元组；候选码是在超码中删去任何一个属性后都不再具有唯一标识能力的集合。这里的“最小”指没有冗余属性，不是所有候选码的属性数必须一样多。","从候选码中选一个作为主码；主码可以由多个属性联合构成。一张表至多声明一个主键，但这个主键可以包含多列。","例如选课关系可用“学号、课程号”共同标识一条选课；学号单独出现多次，不代表联合主键有重复。","SQL主键约束要求唯一且非空；普通UNIQUE约束对NULL的处理依数据库及设置而异，不能直接当成主键。","外键用于参照完整性，本列通常可以重复；它引用主键或受支持的唯一键，是否允许空值还取决于非空约束等设置。","候选码要由业务规则保证唯一，不能因为眼前几行姓名恰好没有重复，就断言姓名能永久作为候选码。","关系模型中的关系是元组的集合，行的先后顺序不承担唯一标识作用，完全相同的元组不重复出现；SQL表若未设置相应约束则可能存有重复行。不能仅因画成二维表，就忽略关系的模型约束。"],"boundary":"域不是某一行或当前列中已经出现的值；候选码不只是“能唯一”的任意属性集合，也不是只能含一列。“字段/记录”与“属性/元组”应按表和关系模型语境区分。","id":"y2023q14","sources":[{"year":2023,"q":14,"type":"单选"}],"keys":["2023-14"],"comparison":{"headers":["概念","判断依据"],"rows":[["域","该属性允许出现哪些值"],["超码","能否唯一标识元组"],["候选码","唯一标识且不存在多余属性"],["主码","从候选码中选定，SQL约束要求唯一且非空"],["外键","非空引用值是否对应合法的被引用键"]]},"pointGroups":[{"title":"先认出关系、元组、属性与域","indices":[0,7]},{"title":"再判断超码、候选码与主码","indices":[1,2,3,4,6]},{"title":"用外键保持参照关系","indices":[5]}],"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多常在多端保存外键，多对多常用关联表；联合主键是否重复要看整组属性。"},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"插入新记录时，主键、非空、唯一和外键约束都会检查，定义正确不代表任意值都可写入。"},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"外键与其他约束也可能限制删除或触发级联，DELETE的作用不能只由WHERE单独推断。"}]},{"q":15,"chapter":10,"section":"10.1","type":"单选","topic":"SQL更新","title":"UPDATE修改已有记录中的字段值","trigger":"题目要求选择用于修改关系表中已有数据的SQL命令。","conclusion":"UPDATE用于更新已有记录；SET指定新值，WHERE限定被修改的记录。","points":["基本形式为UPDATE 表名 SET 字段=值 WHERE 条件。例如UPDATE 学生 SET 成绩=成绩+5 WHERE 学号='01'，表示先找到学号01的记录，再把原成绩加5写回；原来65会变为70。","WHERE控制修改哪些行，SET控制这些行中的哪些列。省略WHERE通常针对全部记录；条件一行也未命中时可修改0行，未列在SET中的普通字段保持原值。","INSERT添加记录，DELETE删除记录，ALTER修改表结构。"],"boundary":"执行更新前应先用相同WHERE条件查询核对；UPDATE改数据，不负责修改字段结构。","id":"y2023q15","sources":[{"year":2023,"q":15,"type":"单选"}],"keys":["2023-15"],"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"先用同一WHERE查询目标行，再理解UPDATE将修改哪些已有记录；查询结果排序不会改变源值。"},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"UPDATE改已有行中的值，INSERT添加新行，可用同一业务场景判断应修改还是追加。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"字段值改变用UPDATE，字段定义或约束改变用ALTER TABLE，须先判断操作的数据层级。"}],"pointGroups":null},{"q":36,"chapter":10,"section":"10.1","type":"判断","topic":"SQL删除","title":"DELETE删除满足条件的记录，不删除表结构","trigger":"题目解释DELETE FROM student WHERE 班级=\"一班\"的作用。","conclusion":"DELETE FROM student WHERE 班级=&#39;一班&#39;删除符合条件的记录并保留表结构；省略WHERE会针对全部行，DROP TABLE才移除整个表对象。","points":["WHERE决定DELETE或UPDATE的作用行；条件没有命中时可影响0行，这本身不表示语法错误。","DELETE FROM student执行后，即使没有剩余记录，student的字段和表对象仍存在；DROP TABLE student后，再查询该表应报告表不存在。","UPDATE用SET改已有记录的字段值；INSERT增加记录；ALTER TABLE改变字段、约束等结构，不能把删列当成DELETE。","ALTER TABLE新增字段后，已有记录的新字段取默认值；未指定默认值时通常为NULL。增加非空字段时须考虑已有数据能否满足约束。","TRUNCATE清空整表并保留表对象，但支持情况、触发器和事务行为依DBMS而异；不能背成“所有数据库中都不可回滚”，例如PostgreSQL的TRUNCATE可随事务回滚。","真正执行仍受权限、外键约束和触发器等限制；某些删除可能被拒绝或触发级联，不能用命令名称保证它一定成功。"],"boundary":"字符串通常用单引号，规范示例写WHERE 班级=&#39;一班&#39;；删行、改值、增删字段与删整表是不同层级，执行前应核对对象和条件。","id":"y2024q36","sources":[{"year":2024,"q":36,"type":"判断"},{"year":2022,"q":46,"type":"填空"}],"keys":["2024-36","2022-46"],"comparison":{"headers":["命令","主要对象","典型结果"],"rows":[["SELECT","查询结果","读取数据"],["INSERT","新记录","行数增加，仍检查约束"],["UPDATE…SET…WHERE…","命中的已有记录","字段值改变"],["DELETE…WHERE…","命中的已有记录","行移除，表结构保留"],["ALTER TABLE","表定义","增加、移除或修改字段及约束"],["DROP TABLE","整个表对象","表及其数据不再存在"]]},"related":[{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"DELETE和UPDATE都用WHERE限定作用行，但前者移除记录，后者通过SET修改字段值。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"删行、删列与删表对象属于不同层级，ALTER TABLE修改结构，DROP TABLE移除表。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"参照完整性可限制记录删除；主外键关系解释了为何有些DELETE会失败或发生级联。"}],"pointGroups":[{"title":"用条件确定作用行并区分操作层级","indices":[0,1,2]},{"title":"结构变化、整表清空与执行约束","indices":[3,4,5]}]},{"q":47,"chapter":10,"section":"10.1","type":"填空","topic":"SQL表结构","title":"ALTER TABLE用于修改已有表结构","trigger":"题目要求向已有数据表添加年龄字段。","conclusion":"可使用ALTER TABLE 表名 ADD 年龄 数据类型，向表中增加字段；具体数据类型和关键字细节由DBMS决定。","points":["ALTER修改数据库对象结构。","INSERT新增记录，UPDATE修改记录值。","添加非空字段时还要考虑已有记录的默认值。","CREATE TABLE创建表，ALTER TABLE修改表结构，DROP TABLE移除表；UPDATE修改已有记录的字段值，DELETE删除记录，层次不同。"],"boundary":"改表结构可能锁表或影响应用，生产环境应先评估兼容性、备份和迁移方案。","id":"y2024q47","sources":[{"year":2024,"q":47,"type":"填空"},{"year":2021,"q":35,"type":"填空","page":6}],"keys":["2024-47","2021-35"],"related":[{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"给表增加字段使用ALTER，给表增加记录使用INSERT，可用列与行的变化辨认命令。"},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"进一步比较删记录、清空记录、调整字段与移除表对象，避免把结构变化当作DELETE。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"新增非空、主键或外键等约束前，要检查已有数据是否符合这些约束所表达的业务规则。"}]},{"q":12,"chapter":10,"section":"10.1","type":"单选","topic":"SQL写入","title":"INSERT向表中添加新记录","trigger":"题目要求选择把新生记录加入信息表的SQL命令。","conclusion":"INSERT用于插入新记录；SELECT查询，DELETE删除记录，ALTER修改数据库对象结构。","points":["常见形式是INSERT INTO 表名(字段) VALUES(值)。","字段与值的数量、顺序和数据类型应对应。","主键、非空、唯一和外键约束仍会检查新记录。"],"boundary":"ALTER用于改表结构，不用于把普通记录追加到表中。","id":"y2025q12","sources":[{"year":2025,"q":12,"type":"单选"}],"keys":["2025-12"],"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"字段与值对应正确后，还须满足主键唯一非空及外键参照等条件，才能成功新增记录。"},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"新增记录用INSERT，修改已存在记录用UPDATE；是否已经有目标行决定操作选择。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"INSERT增加行而不增加字段，补充字段定义要修改表结构。"}]},{"q":13,"chapter":10,"section":"10.2","type":"单选","topic":"数据库系统","title":"数据库、DBMS与数据库系统不是同一层级","trigger":"真题从Access、DBA、系统构成和核心软件关系考查数据库基本概念。","conclusion":"数据库是数据集合，DBMS是管理数据库的核心软件，数据库系统还包括应用、人员和运行环境；Access属于关系DBMS。","points":["DBMS负责定义、存取、控制、恢复和并发管理等。","DBA负责权限、备份恢复、性能与可用性。","数据库系统比文件系统提供更强的数据共享和一致性管理。"],"boundary":"DB、DBMS和DBS不能互换；应说DBMS是数据库系统的核心软件，而不是反过来。","id":"y2020q13","sources":[{"year":2020,"q":13,"type":"单选"},{"year":2023,"q":36,"type":"判断"},{"year":2024,"q":27,"type":"多选"}],"keys":["2020-13","2023-36","2024-27"],"related":[{"id":"y2025q42","label":"数据库运维工作由数据库管理员负责","reason":"DBMS是管理软件，DBA是负责配置、安全和运维的人员，二者名称相近但层级不同。"},{"id":"merged-2","label":"系统软件与应用软件按功能区分","reason":"软件按主要功能分类，不能因名称含系统或随系统附带就判断其类别；DBMS也要按管理职责理解。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"拥有DBMS不等于已完成数据库设计，还须经过需求、概念、逻辑和物理设计。"}]},{"q":42,"chapter":10,"section":"10.2","type":"填空","topic":"数据库人员","title":"数据库运维工作由数据库管理员负责","trigger":"题目在数据库管理人员分类中判断负责数据库运维的角色。","conclusion":"数据库管理员DBA负责数据库安装配置、权限、安全、备份恢复、性能监控和日常运行维护。","points":["系统分析员侧重需求与系统方案。","应用程序员负责开发访问数据库的业务程序。","DBA还需管理账户、容量、日志和故障恢复。"],"boundary":"DBA不是所有数据内容的业务负责人，权限与职责仍应分离。","id":"y2025q42","sources":[{"year":2025,"q":42,"type":"填空"}],"keys":["2025-42"],"related":[{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"在数据库系统组成中定位DBA与DBMS，区分人员责任、核心管理软件和数据集合。"},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"备份恢复、监控和故障处理服务于可用性等安全目标，能据题干后果辨认运维重点。"}]},{"q":14,"chapter":10,"section":"10.3","type":"单选","topic":"实体联系","title":"一对一、一对多和多对多联系要双向判断","trigger":"题目描述一个团支部有多名团员，而一个团员只属于一个团支部。","conclusion":"联系基数由业务规则决定：从两端分别判断一个实例最多可对应几个实例，再区分一对一、一对多与多对多。","points":["一对一表示双方每个实体最多对应另一方一个实体。","一对多常在“多”端保存“一”端的主键作外键。例如每名学生只属于一个班级，而一班可有多名学生：学生表保存班级号，多名学生的班级号可相同。","多对多通常用关联表拆成两个一对多。例如学生可选多门课、每门课可被多人选：选课表的一行记录一名学生与一门课程，分别用学号、课程号参照学生表和课程表。","判断联系必须双向看：一家出版社可向多家书店供书，一家书店也可向多家出版社进货，因此是多对多。具体基数取决于业务规则。"],"boundary":"关系方向会影响措辞，但不会改变结构本质；判断时分别看两端最大对应数量。","id":"y2020q14","sources":[{"year":2020,"q":14,"type":"单选"},{"year":2022,"q":13,"type":"单选"}],"keys":["2020-14","2022-13"],"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"把业务联系落到表结构时，一对多使用外键、多对多使用关联表，需同时检查键的唯一性与空值规则。"},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"先在概念设计中表达实体联系，再在逻辑设计中形成关系模式，联系基数不能由当前样本随意决定。"},{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"连接必须产生所有符合条件的匹配组合，一对多或多对多会影响输出行数。"}],"pointGroups":null,"workedExamples":[{"year":2020,"q":14,"questionSummary":"由团支部与团员的双向业务约束判断联系类型。","reasoning":["固定一个团支部，可以找到多名团员。","固定一名团员，题设只允许归属一个团支部。","按“团支部→团员”的方向是1对多；联系类型须连同提问方向一起读。"],"pitfall":"只看“多人”而不做反向检查，或把题目实体顺序倒置。","transfer":"判断教师与课程等新情境时不能套常识，要先问一个A对应几个B，再问一个B对应几个A。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"公开转录题面已读，原卷扫描待核","historicalVersionNote":""}]},{"q":26,"chapter":10,"section":"10.3","type":"多选","topic":"NoSQL与图数据库","title":"NoSQL按数据模型与访问需求选型","trigger":"真题从模型灵活性、查询语言、一致性取舍和社交关系网络选择考查NoSQL。","conclusion":"NoSQL常强调灵活模型与横向扩展；不同产品在一致性、可用性和扩展性间取舍，图数据库则适合多跳关联和路径分析。","points":["常见类型包括键值、文档、列族和图数据库。","NoSQL没有一套所有产品统一采用的标准查询语言。","选型还要评估事务、查询模式、数据结构和运维成本。","宽列/列族数据库是常见NoSQL模型之一；关系数据库也可采用列式存储，不能见到“按列存储”就断言一定是NoSQL。","模型灵活、水平扩展与大规模存储是许多NoSQL产品的适用方向；复杂查询能力、事务和一致性保证必须按具体产品判断，不是所有NoSQL都弱或都强。","键值模型以键定位对应值，适合按标识快速读写的缓存或会话数据；文档模型保存带字段的文档，适合字段结构可变化的对象资料。","列族模型按行键组织数据并按列族管理相关列，适合按预先设计的访问模式处理大规模稀疏数据；它与关系数据库的列式分析存储不是同一概念。","图模型把实体与关系作为节点和边，适合社交关系、多跳推荐和路径分析；“数据量大”本身不足以决定必须使用图数据库。","教学选择流程：先写出常用查询，再看记录结构、关系深度与更新方式，最后比较一致性、事务、扩展和运维要求。"],"boundary":"NoSQL不是“不查询”或“永远不要一致性”，图数据库也不是所有大数据场景的默认答案。","id":"y2026q12","sources":[{"year":2023,"q":26,"type":"多选"},{"year":2024,"q":15,"type":"单选"},{"year":2026,"q":12,"type":"单选"},{"year":2022,"q":35,"type":"判断"},{"year":2021,"q":27,"type":"多选","page":5}],"keys":["2023-26","2024-15","2026-12","2022-35","2021-27"],"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"数据的规模、速度和类型可解释选型需求，但仍要具体评估查询、事务、一致性和运维成本。"},{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"先区分数据集合、管理软件与整个数据库系统，再讨论关系和NoSQL产品适合什么数据模型。"}],"pointGroups":[{"title":"辨认模型、查询语言与列式存储","indices":[0,1,3]},{"title":"按事务、查询与运维需求评估","indices":[2,4]},{"title":"先看数据形态和访问方式，再选NoSQL模型","indices":[5,6,7,8]}]},{"q":11,"chapter":10,"section":"10.3","type":"单选","topic":"数据库设计","title":"数据库设计不因规模小而省略","trigger":"题目要求找出数据库设计阶段描述中的错误项。","conclusion":"数据库设计通常包括需求分析、概念结构、逻辑结构和物理结构等阶段，小型数据库同样需要与规模相称的设计。","points":["需求分析先问清业务要保存什么、要完成什么操作、有哪些限制，例如是否允许学生重复选同一门课；这些规则决定后续模型。","概念结构设计用E-R模型表示实体、属性和联系，例如“学生—选课—课程”；此时重在表达业务，通常不依赖具体DBMS。","物理结构设计决定数据怎样存放和高效访问，例如为常按学号查询的选课记录考虑索引；存储方法、文件组织和索引属于这一层。","逻辑结构设计把概念模型转为关系模式，例如学生(学号,姓名)、课程(课程号,课名)、选课(学号,课程号,成绩)，再明确主键、外键等约束。顺序可复述为：明确需求→画业务联系→形成表与约束→安排存储和访问。"],"boundary":"规模小可以简化文档和过程，但不能等同于“不需要设计”。","id":"y2025q11","sources":[{"year":2025,"q":11,"type":"单选"},{"year":2021,"q":14,"type":"单选","page":3}],"keys":["2025-11","2021-14"],"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"E-R概念设计需要由业务规则双向判断一对一、一对多或多对多联系。"},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"从概念模型转成关系模式后，需要明确属性、域、候选码、主键和外键约束。"},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"设计确定或调整字段及约束后，ALTER TABLE是修改已有表结构的实现入口之一。"}],"pointGroups":null}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"merged-20":[["Emory大学：选择、投影、笛卡尔积与连接","https://www.cs.emory.edu/~cheung/Courses/554/Syllabus/1-intro/intro4.html"],["PostgreSQL：连接条件、USING与自然连接","https://www.postgresql.org/docs/current/queries-table-expressions.html"],["PostgreSQL：并、交、差及相容性","https://www.postgresql.org/docs/current/queries-union.html"]],"merged-21":[["SQLite：SELECT的DISTINCT、WHERE与ORDER BY语义","https://www.sqlite.org/lang_select.html"],["PostgreSQL：比较运算与NULL判断","https://www.postgresql.org/docs/current/functions-comparison.html"]],"y2023q14":[["Emory大学：关系及超码、候选码、主码","https://www.cs.emory.edu/~cheung/Courses/554/Syllabus/1-intro/relation.html"],["PostgreSQL：主键、唯一与外键约束","https://www.postgresql.org/docs/current/ddl-constraints.html"]],"y2023q15":[["PostgreSQL：UPDATE的条件、旧值表达式与保留列","https://www.postgresql.org/docs/current/sql-update.html"]],"y2024q36":[["PostgreSQL：DELETE","https://www.postgresql.org/docs/current/sql-delete.html"],["PostgreSQL：UPDATE","https://www.postgresql.org/docs/current/sql-update.html"],["PostgreSQL：DROP TABLE","https://www.postgresql.org/docs/current/sql-droptable.html"],["PostgreSQL：ALTER TABLE及新增字段默认值","https://www.postgresql.org/docs/current/ddl-alter.html"],["PostgreSQL：TRUNCATE的事务与约束行为","https://www.postgresql.org/docs/current/sql-truncate.html"]],"y2020q14":[["PostgreSQL：用外键及关联表实现多对多","https://www.postgresql.org/docs/current/ddl-constraints.html"]],"y2025q11":[["AWS：概念、逻辑与物理数据模型的职责","https://aws.amazon.com/compare/the-difference-between-logical-and-physical-data-model/"]]};
window.NOTE_DEMOS={"y2024q47":{"kind":"sequence","title":"安全地给学生表增加年龄列","task":"在SQL工作台中检查结构、执行ALTER并验证结果。","steps":[{"label":"查看现有表结构","detail":"确认字段名、命名规则和兼容性。"},{"label":"编写ALTER TABLE","detail":"写ALTER TABLE student ADD 年龄 INT。"},{"label":"执行并处理已有记录","detail":"新增列后旧记录通常先为NULL或使用默认值。"},{"label":"查询结构验证","detail":"确认字段类型、约束和应用读写都正常。"}]},"y2025q12":{"kind":"sequence","title":"向新生信息表插入一行","task":"在SQL工作台中组装并执行INSERT语句。","steps":[{"label":"选择目标表与字段","detail":"明确写入新生信息表的学号、姓名等列。"},{"label":"填写VALUES","detail":"值的数量、顺序和数据类型与字段对应。"},{"label":"执行INSERT","detail":"数据库检查主键、非空和外键约束。"},{"label":"查询验证","detail":"用SELECT确认新记录已经写入。"}]},"y2020q13":{"kind":"explore","title":"分清数据库与DBMS","task":"点击对象，观察它是数据集合、管理软件还是数据模型。","initial":"Access是关系数据库管理系统。","actions":[{"label":"一个.accdb文件","stage":"数据库","result":"保存表、查询等数据库对象和数据。","tone":"good"},{"label":"Microsoft Access","stage":"数据库管理系统DBMS","result":"用于创建、维护和访问数据库。","tone":"good"},{"label":"二维表及其关系","stage":"关系模型","result":"用字段、记录、主键和联系组织数据。","tone":"good"},{"label":"Word表格","stage":"不是关系数据库的充分条件","result":"看起来是二维表不代表具备数据库约束与管理能力。","tone":"warn"}]},"y2025q42":{"kind":"explore","title":"进入DBA值班台","task":"点击一次数据库事件，判断该由哪个角色负责。","initial":"生产数据库正在运行。","actions":[{"label":"定时备份与恢复演练","stage":"数据库管理员DBA","result":"保障故障后可恢复。","tone":"good"},{"label":"账户与权限审计","stage":"数据库管理员DBA","result":"落实最小权限和追踪。","tone":"good"},{"label":"设计业务需求流程","stage":"系统分析员主导","result":"职责侧重需求与方案。","tone":"warn"},{"label":"开发挂号页面","stage":"应用程序员主导","result":"通过程序访问数据库。","tone":"warn"}]},"y2026q12":{"kind":"explore","title":"给数据场景选模型","task":"点击需求，观察NoSQL与关系数据库各自的取舍。","initial":"选型要看数据结构、事务、查询和扩展需求。","actions":[{"label":"字段经常变化的文档","stage":"文档型NoSQL较灵活","result":"同一集合中的文档结构可不完全一致。","tone":"good"},{"label":"海量键值高速访问","stage":"键值数据库适合","result":"按键直接读写，模型简单。","tone":"good"},{"label":"复杂事务与多表约束","stage":"关系数据库通常更自然","result":"成熟SQL、事务和约束能力是优势。","tone":"good"},{"label":"NoSQL一定更快且无一致性","stage":"错误绝对化","result":"性能和一致性取决于具体产品、配置与负载。","tone":"bad"}]},"y2025q11":{"kind":"sequence","title":"把需求逐层变成数据库","task":"按设计阶段把“新生信息系统”从业务语言落到存储结构。","steps":[{"label":"需求分析","detail":"确认要管理谁、做什么查询和遵守哪些业务规则。"},{"label":"概念结构设计","detail":"用E-R图表达实体、属性和联系，不绑定具体DBMS。"},{"label":"逻辑结构设计","detail":"转换为关系表、主键、外键和约束。"},{"label":"物理结构设计","detail":"选择文件组织、索引和具体存储方法。"}]}};
window.NOTE_NAVIGATION={"merged-20":{"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"把筛行、取列映射到WHERE和SELECT，同时注意关系代数投影去重与SQL默认保留重复的差别。","chapter":10},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"理解连接匹配和结果重复前，先分清属性、主键、外键及某列是否由业务规则保证唯一。","chapter":10},{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多、多对多联系决定跨表匹配的可能数量，连接不能按屏幕行号机械拼接。","chapter":10}],"topics":[{"id":"cmp-table-filter-summary","title":"表格结果变少：筛选、去重与汇总各做了什么？"}]},"merged-21":{"related":[{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"用关系代数区分选择行、投影列和连接来源，解释SELECT命令并不只对应其中的选择运算。","chapter":10},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"UPDATE前可用相同WHERE查询核对目标行，查询条件的理解直接决定修改范围。","chapter":10},{"id":"y2020q9","label":"高级筛选同一行是AND，不同行是OR","reason":"SQL筛行和Excel高级筛选都要求正确组合条件，同行AND、异行OR可帮助练习条件分组。","chapter":4}],"topics":[{"id":"cmp-table-filter-summary","title":"表格结果变少：筛选、去重与汇总各做了什么？"}]},"y2023q14":{"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"一对多常在多端保存外键，多对多常用关联表；联合主键是否重复要看整组属性。","chapter":10},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"插入新记录时，主键、非空、唯一和外键约束都会检查，定义正确不代表任意值都可写入。","chapter":10},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"外键与其他约束也可能限制删除或触发级联，DELETE的作用不能只由WHERE单独推断。","chapter":10}],"topics":[]},"y2023q15":{"related":[{"id":"merged-21","label":"SELECT查询与字段选择","reason":"先用同一WHERE查询目标行，再理解UPDATE将修改哪些已有记录；查询结果排序不会改变源值。","chapter":10},{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"UPDATE改已有行中的值，INSERT添加新行，可用同一业务场景判断应修改还是追加。","chapter":10},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"字段值改变用UPDATE，字段定义或约束改变用ALTER TABLE，须先判断操作的数据层级。","chapter":10}],"topics":[]},"y2024q36":{"related":[{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"DELETE和UPDATE都用WHERE限定作用行，但前者移除记录，后者通过SET修改字段值。","chapter":10},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"删行、删列与删表对象属于不同层级，ALTER TABLE修改结构，DROP TABLE移除表。","chapter":10},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"参照完整性可限制记录删除；主外键关系解释了为何有些DELETE会失败或发生级联。","chapter":10}],"topics":[{"id":"cmp-delete-context","title":"同一个Delete，作用对象可能完全不同"}]},"y2024q47":{"related":[{"id":"y2025q12","label":"INSERT向表中添加新记录","reason":"给表增加字段使用ALTER，给表增加记录使用INSERT，可用列与行的变化辨认命令。","chapter":10},{"id":"y2024q36","label":"DELETE删除满足条件的记录，不删除表结构","reason":"进一步比较删记录、清空记录、调整字段与移除表对象，避免把结构变化当作DELETE。","chapter":10},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"新增非空、主键或外键等约束前，要检查已有数据是否符合这些约束所表达的业务规则。","chapter":10}],"topics":[]},"y2025q12":{"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"字段与值对应正确后，还须满足主键唯一非空及外键参照等条件，才能成功新增记录。","chapter":10},{"id":"y2023q15","label":"UPDATE修改已有记录中的字段值","reason":"新增记录用INSERT，修改已存在记录用UPDATE；是否已经有目标行决定操作选择。","chapter":10},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"INSERT增加行而不增加字段，补充字段定义要修改表结构。","chapter":10}],"topics":[]},"y2020q13":{"related":[{"id":"y2025q42","label":"数据库运维工作由数据库管理员负责","reason":"DBMS是管理软件，DBA是负责配置、安全和运维的人员，二者名称相近但层级不同。","chapter":10},{"id":"merged-2","label":"系统软件与应用软件按功能区分","reason":"软件按主要功能分类，不能因名称含系统或随系统附带就判断其类别；DBMS也要按管理职责理解。","chapter":1},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"拥有DBMS不等于已完成数据库设计，还须经过需求、概念、逻辑和物理设计。","chapter":10}],"topics":[]},"y2025q42":{"related":[{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"在数据库系统组成中定位DBA与DBMS，区分人员责任、核心管理软件和数据集合。","chapter":10},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"备份恢复、监控和故障处理服务于可用性等安全目标，能据题干后果辨认运维重点。","chapter":8}],"topics":[]},"y2020q14":{"related":[{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"把业务联系落到表结构时，一对多使用外键、多对多使用关联表，需同时检查键的唯一性与空值规则。","chapter":10},{"id":"y2025q11","label":"数据库设计不因规模小而省略","reason":"先在概念设计中表达实体联系，再在逻辑设计中形成关系模式，联系基数不能由当前样本随意决定。","chapter":10},{"id":"merged-20","label":"选择、投影、连接与集合运算","reason":"连接必须产生所有符合条件的匹配组合，一对多或多对多会影响输出行数。","chapter":10}],"topics":[]},"y2026q12":{"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"数据的规模、速度和类型可解释选型需求，但仍要具体评估查询、事务、一致性和运维成本。","chapter":9},{"id":"y2020q13","label":"数据库、DBMS与数据库系统不是同一层级","reason":"先区分数据集合、管理软件与整个数据库系统，再讨论关系和NoSQL产品适合什么数据模型。","chapter":10}],"topics":[]},"y2025q11":{"related":[{"id":"y2020q14","label":"一对一、一对多和多对多联系要双向判断","reason":"E-R概念设计需要由业务规则双向判断一对一、一对多或多对多联系。","chapter":10},{"id":"y2023q14","label":"属性、域、候选码、主键与外键要分层判断","reason":"从概念模型转成关系模式后，需要明确属性、域、候选码、主键和外键约束。","chapter":10},{"id":"y2024q47","label":"ALTER TABLE用于修改已有表结构","reason":"设计确定或调整字段及约束后，ALTER TABLE是修改已有表结构的实现入口之一。","chapter":10}],"topics":[]}};
